251	\subsubsection{Consistency between measurements}
252	
253	The most basic notion of similarity between two measurements is given by their \emph{consistency}.
254	
255	\begin{definition}[Consistency]\label{def:simeq}
256	Let $\ket{\psi}$ be a state in $\calH_{\mathrm{A}} \ot \calH_{\mathrm{B}}$.
257	Let $A = \{A^x_a\}$ be a sub-measurement acting on $\calH_{\mathrm{A}}$
258	and $B = \{B^x_a\}$ be a sub-measurement acting on $\calH_{\mathrm{B}}$.
259	Finally, let $\calD$ be a distribution on the question set~$\calX$.
260	Then we say that
261	 \begin{equation*}
262	 A^x_a \ot I \simeq_{\delta} I \ot B^x_a
263	 \end{equation*}
264	  on state $\ket{\psi}$ and distribution $\calD$ if
265	  \begin{equation}\label{eq:no-big-Oh}
266	  \E_{\bx \sim \calD} \sum_{a \neq b} \bra{\psi} A^{\bx}_a \ot B^{\bx}_b
267	    \ket{\psi} \leq \delta.
268	    \end{equation}
269	\end{definition}
270	
271	This is simply the probability that the provers receive different outcomes
272	when they measure with~$A$ and~$B$,
273	assuming the sub-measurements do return an outcome.
274	
275	\begin{notation}[Simplifying notation]
276	Because the state $\ket{\psi}$ and distribution $\calD$ are typically clear from context,
277	we will often write ``$ A^x_a \ot I \simeq_{\delta} I \ot B^x_a$"
278	as shorthand for ``$ A^x_a \ot I \simeq_{\delta} I \ot B^x_a$ on state $\ket{\psi}$ and distribution $\calD$".
279	In the case when $\calD$ is not clear by context,
280	we might specify it implicitly in terms of a random variable~$\bx$ distributed according to~$\calD$.
281	For example, suppose the distribution~$\calD$ is supposed to be uniform on the question set $\F_q$.
282	Then we might say ``on average over $\bx \sim \F_q$,
283	\begin{equation*}
284	A^x_a \ot I \simeq_{\delta} I \ot B^x_a"
285	\end{equation*}
286	as shorthand for ``$ A^x_a \ot I \simeq_{\delta} I \ot B^x_a$ on distribution $\calD$".
287	\end{notation}
288	
289	We note that there are two differences between the definition of consistency in \Cref{def:simeq}
290	and the original definition of consistency given in \cite[Definition 4.11]{NW19}.
291	The first of these is that the~\cite{NW19} definition
292	allows the right-hand side of \Cref{eq:no-big-Oh} to be $O(\delta)$
293	rather than strictly~$\delta$.
294	The benefit of this is that they do not need to keep track of constant prefactors in their proofs;
295	we have elected to use this more concrete definition
296	to make our proofs more easily verifiable, at the expense of tracking these constant prefactors.
297	The second difference is that is that they define their consistency as the quantity
298	\begin{equation*}
299	1 - \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi}.
300	\end{equation*}
301	As we show below in \Cref{prop:simeq-for-measurements},
302	this agrees with \Cref{def:simeq}
303	when~$A$ and~$B$ are both measurements.
304	However, these two definitions disagree
305	when~$A$ and~$B$ are \emph{sub}-measurements,
306	which is a case we will frequently encounter throughout this paper.
307	
308	\begin{proposition}[Consistency for measurements]\label{prop:simeq-for-measurements}
309	Let $A = \{A^x_a\}$ and $B = \{B^x_a\}$ be two measurements.
310	Then
311	\begin{equation*}
312	A^x_a \ot I \simeq_{\delta} I \ot B^x_a
313	\end{equation*}
314	if and only if
315	\begin{equation*}
316	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi} \geq 1 - \delta.
317	\end{equation*}
318	\end{proposition}
319	\begin{proof}
320	We compute
321	\begin{align*}
322	&\E_{\bx} \sum_{a \neq b}\bra{\psi} A^{\bx}_a \ot B^{\bx}_b \ket{\psi}\\
323	=~& \E_{\bx} \sum_b \bra{\psi} \Big(\sum_{a \neq b} A^{\bx}_a\Big) \ot B^{\bx}_b\ket{\psi}\\
324	=~&\E_{\bx} \sum_b \bra{\psi} (I - A^{\bx}_b) \ot B^{\bx}_b\ket{\psi}
325		\tag{because~$A$ is a measurement}\\
326	=~&\E_{\bx} \sum_b \bra{\psi} I \ot B^{\bx}_b\ket{\psi}
327		- \E_{\bx} \sum_b \bra{\psi} A^{\bx}_b \ot B^{\bx}_b\ket{\psi}\\
328	=~&1
329		- \E_{\bx} \sum_b \bra{\psi} A^{\bx}_b \ot B^{\bx}_b\ket{\psi}. \tag{because~$B$ is a measurement}
330	\end{align*}
331	Hence, the first expression is at most~$\delta$ if and only if the last one is as well,
332	and we are done.
333	\end{proof}
334	
335	\subsubsection{The state-dependent distance}
336	
337	Suppose we have three measurements $\{A^x_a\}$, $\{B^x_a\}$, and $\{C^x_a\}$,
338	and we know that
339	\begin{equation*}
340	A^x_a \ot I \simeq_{\eps} I \ot C^x_a.
341	\end{equation*}
342	What property of~$A$ and~$B$ allows us to conclude that
343	\begin{equation}\label{eq:can-we-use-approx-delta-to-derive-this}
344	B^x_a \ot I \simeq_{\eps} I \ot C^x_a?
345	\end{equation}
346	The answer is provided by the \emph{state-dependent distance}.
347	
348	\begin{definition}[The state-dependent distance]\label{def:approx_delta}
349	Let $\ket{\psi}$ be a state in $\calH$.
350	Let $A = \{A^x_a\}$ and $B = \{B^x_a\}$ be
351	sets of matrices acting on $\calH$.
352	Finally, let $\calD$ be a distribution on the question set~$\calX$.
353	Then we say that
354	  \begin{equation*}
355	  A^x_a \approx_{\delta}  B^x_a
356	  \end{equation*}
357	 on state $\ket{\psi}$ and distribution $\calD$ if
358	  \begin{equation*}
359	  \E_{\bx \sim \calD} \sum_{a} \Vert (A^{\bx}_a - B^{\bx}_a) \ket{\psi} \Vert^2 \leq \delta.
360	    \end{equation*}
361	\end{definition}
362	
363	We note one odd feature of \Cref{def:approx_delta} in comparison to the consistency,
364	which is that $\ket{\psi}$ is not assumed to have a bipartition $\calH_{\mathrm{A}} \ot \calH_{\mathrm{B}}$
365	in which~$A$ and~$B$ are applied on opposite sides.
366	We will address this in \Cref{sec:consistency-from-state-dependent-distance} below.
367	Before doing so, we will answer our question above,
368	even in the case when~$C$ is allowed to be a sub-measurement. 
369	
370	\begin{proposition}[Transfering ``$\simeq$" using ``$\approx$"]
371	Let $\{A^x_a\}$ and $\{B^x_a\}$ be measurements,
372	and let $\{C^x_a\}$ be a sub-measurement.
373	Suppose that $A^x_a \ot I \simeq_{\delta} I \ot C^x_a$
374	and $A^x_a \ot I \approx_{\eps} B^x_a \ot I$.
375	Then $B^x_a \ot I \simeq_{\delta + \sqrt{\eps}} I \ot C^x_a$.
376	  \label{prop:triangle-sub}
377	\end{proposition}
378	
379	
380	\begin{proof}
381	  First, we can
382	  rewrite the consistency between $A$ and $C$ as
383	  \begin{align*}
384	    \delta \geq \E_{\bx} \sum_{a \neq b} \bra{\psi} A^{\bx}_a \ot C^{\bx}_b
385	    \ket{\psi} 
386	    & = \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot (C^{\bx} - C^{\bx}_a) \ket{\psi} \\
387	    & =  \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot C^{\bx} \ket{\psi}
388	    			- \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot C^{\bx}_a \ket{\psi} \\
389	    & =  \E_{\bx} \bra{\psi} I \ot C^{\bx} \ket{\psi}
390	    			- \E_{\bx} \sum_{a} \bra{\psi} A^{\bx}_a \ot C^{\bx}_a \ket{\psi} \tag{because~$A$ is a measurement}\\
391	    & = \bra{\psi} I \ot C \ket{\psi} - \E_{\bx} \sum_a
392	                 \bra{\psi} A^{\bx}_a \ot C^{\bx}_a \ket{\psi}.
393	  \end{align*}
394	  Likewise, we can rewrite the
395	  inconsistency between $B$ and $C$ as
396	  \begin{align*}
397	    \E_{\bx} \sum_{a \neq b} \bra{\psi} B^{\bx}_a \ot C^{\bx}_b
398	    \ket{\psi} &= \bra{\psi} I \ot C \ket{\psi} - \E_{\bx} \sum_a
399	                 \bra{\psi} B^{\bx}_a \ot C^{\bx}_a \ket{\psi}.
400	  \end{align*}
401	  We want to show that the inconsistency between~$B$ and~$C$ is close to the inconsistency between $A$
402	  and $B$. In particular, we claim that
403	  \begin{equation*}
404	  \E_{\bx} \sum_{a \neq b} \bra{\psi} A^{\bx}_a \ot C^{\bx}_b
405	    \ket{\psi}
406	    \approx_{\sqrt{\eps}} \E_{\bx} \sum_{a \neq b} \bra{\psi} B^{\bx}_a \ot C^{\bx}_b
407	    \ket{\psi}.
408	  \end{equation*}
409	  To show this, we bound the magnitude of the difference using Cauchy-Schwarz.
410	  \begin{align*}
411	   & \Big| \E_{\bx} \sum_{a } \bra{\psi} (A^{\bx}_a - B^{\bx}_a) \ot
412	                     C^{\bx}_a\ket{\psi} \Big| \nonumber
413	    \\
414	    \leq~& \sqrt{ \E_{\bx} \sum_{a} \bra{\psi}
415	                            (A^{\bx}_a - B^{\bx}_a)^2 \ot I \ket{\psi}}
416	                            \cdot \sqrt{\E_{\bx} \sum_{a} \bra{\psi} I \ot (C^{\bx}_a)^2 \ket{\psi}} \\
417	    \leq~& \sqrt{\eps} \cdot 1. \tag{because~$C$ is a sub-measurement}
418	  \end{align*}
419	  This completes the proof.
420	\end{proof}
421	
422	
423	Next, we show that in the case of measurements,
424	the state-dependent distance is a weakening of the consistency.
425	
426	\begin{proposition}[``$\simeq$" implies ``$\approx$" for measurements]\label{prop:simeq-to-approx}
427	Let $A = \{A^x_a\}$ and $B = \{B^x_a\}$ be two measurements such that
428	\begin{equation*}
429	A^x_a \ot I \simeq_{\delta} I \ot B^x_a.
430	\end{equation*}

430	\end{equation*}
431	Then
432	\begin{equation*}
433	A^x_a \ot I \approx_{2\delta} I \ot B^x_a.
434	\end{equation*}
435	This is an ``if and only if'' if~$A$ and~$B$ are both projective measurements.
436	\end{proposition}
437	\begin{proof}
438	Our goal is to bound
439	\begin{align*}
440	&\E_{\bx} \sum_a\Vert (A^{\bx}_a \ot I - I \ot B^{\bx}_a) \ket{\psi} \Vert^2\\
441	=~&\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a \ot I - I \ot B^{\bx}_a)^2 \ket{\psi}\\
442	=~&\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a)^2 \ot I \ket{\psi}
443		+\E_{\bx} \sum_a \bra{\psi} I \ot (B^{\bx}_a)^2 \ket{\psi}
444		- 2 \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi}\\
445	\leq~&\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot I \ket{\psi}
446		+\E_{\bx} \sum_a \bra{\psi} I \ot B^{\bx}_a \ket{\psi}
447		- 2 \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi}\\
448	=~&2
449		- 2 \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \ot B^{\bx}_a \ket{\psi} \tag{because~$A$ and~$B$ are measurements}\\
450	\leq~& 2 - 2 \cdot(1-\delta) \tag{by~\Cref{prop:simeq-for-measurements} and the fact that~$A$ and~$B$ are measurements}\\
451	=~&2 \delta.
452	\end{align*}
453	This completes the proof.
454	When  $A$ and~$B$ are projective, ``if and only if'' 
455	follows from the first inequality becoming an equality.
456	\end{proof}
457	
458	
459	\begin{remark}
460	We note that \Cref{prop:simeq-to-approx} certainly does \emph{not} hold for sub-measurements.
461	For example, if $A^x_a = 0$ for all~$a$,
462	then $A_a^x \ot I \simeq_{0} I \ot B_a^x$,
463	but
464	\begin{equation*}
465	\E_{\bx} \sum_a \Vert (A^{\bx}_a \ot I - I \ot B^{\bx}_a)\ket{\psi} \Vert^2
466	= \E_{\bx} \sum_a \Vert (I \ot B^{\bx}_a)\ket{\psi} \Vert^2,
467	\end{equation*}
468	which is nonzero unless $(I \ot B^x_a) \ket{\psi} = 0$ for all~$x$ and~$a$.
469	\end{remark}
