538	\Cref{prop:closeness-of-ip} is broad enough to capture
539	almost all of our applications of the state-dependent distance.
540	Unfortunately, defining the $C^x_{a, b}$ matrices and showing that 
541	they satisfy the inequality $\sum_a (\sum_b C^x_{a,b}) (\sum_b C^x_{a,b})^\dagger  \leq I$
542	can be somewhat cumbersome.
543	As a result, we will usually carry out these Cauchy-Schwarz calculations by hand.
544	However, we will occasionally use the following proposition
545	which simplifies \Cref{prop:closeness-of-ip}.
546	
547	\begin{proposition}\label{prop:easy-approx-from-approx-delta}
548	Let $A = \{A^x_a\}$, $B = \{B^x_a\}$, and $C = \{C^x_a\}$ be sub-measurements
549	such that $A^x_a \approx_{\delta} B^x_a$. Then
550	\begin{equation*}
551	\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a  C^{\bx}_a \ket{\psi}
552	\approx_{\sqrt{\delta}} \E_{\bx} \sum_a \bra{\psi} B^{\bx}_a  C^{\bx}_a \ket{\psi}.
553	\end{equation*}
554	\end{proposition}
555	\begin{proof}
556	To show this, we bound the magnitude of the difference.
557	\begin{align*}
558	&\Big| \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a) \cdot (C^{\bx}_a) \ket{\psi}\Big|\\
559	\leq~& \sqrt{\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a)^2 \ket{\psi}}
560		\cdot \sqrt{\E_{\bx} \sum_a \bra{\psi} (C^{\bx}_a)^2 \ket{\psi}}\\
561	\leq~& \sqrt{\delta} \cdot \sqrt{1}.
562	\end{align*}
563	This completes the proof.
564	\end{proof}
